func (this *StyledTextContentSpec) Test_Delimiter_Special_Cases() {
	var content swt.StyledTextContent = this.GetContentInstance()
	var newText string
	content.SetText("\nL1\r\nL2\r\n")
	content.ReplaceTextRange(7, 2, "")
	newText = content.GetTextRange(0, content.GetCharCount())
	this.AssertTrue(":1:", (newText == "\nL1\r\nL2"))
	content.SetText("L1\r\n")
	content.ReplaceTextRange(2, 2, "test\n\n")
	newText = content.GetTextRange(0, content.GetCharCount())
	this.AssertTrue(":2:", (newText == "L1test\n\n"))
	content.SetText("L1\n")
	content.ReplaceTextRange(2, 0, "test\r\r\r")
	newText = content.GetTextRange(0, content.GetCharCount())
	this.AssertTrue(":3:", (newText == "L1test\r\r\r\n"))
}

func (this *StyledTextContentSpec) SetUp() {
	this.shell = swt.NewShell()
	var layout *swt.GridLayout = swt.NewGridLayout()
	layout.NumColumns = 1
	this.shell.SetSize(500, 300)
	this.shell.SetLayout(upcastswtGridLayoutToswtLayout(layout))
	this.widget = swt.NewStyledText(upcastswtShellToswtComposite(this.shell), swt.BORDER|swt.MULTI|swt.V_SCROLL|swt.H_SCROLL)
	var spec *swt.GridData = swt.NewGridData()
	spec.HorizontalAlignment = swt.GridDataFILL
	spec.GrabExcessHorizontalSpace = true
	spec.VerticalAlignment = swt.GridDataFILL
	spec.GrabExcessVerticalSpace = true
	this.widget.SetLayoutData(spec)
	this.shell.Open()
}

func (this *StyledTextContentSpec) TearDown() {
	if this.shell != (nil) && !this.shell.IsDisposed() {
		this.shell.Dispose()
	}
	this.shell = nil
}

