func StyledTextContentSpecMain(args []string) {
	var spec *StyledTextContentSpec = NewStyledTextContentSpec()
	if int32(len(args)) > 0 {
		StyledTextContentSpecContentClassName = args[0]
	} else {
		var box *swt.MessageBox = swt.NewMessageBoxParentStyle(swt.DisplayGetDefault().GetActiveShell(), swt.ICON_ERROR)
		box.SetMessage("Content class must be specified as an execution argument.")
		box.Open()
		return
	}
	spec.Run()
	fmt.Fprintln(os.Stdout)
	fmt.Fprintln(os.Stdout, fmt.Sprintf("%d TEST FAILURES.", StyledTextContentSpecFailCount))
	fmt.Fprintln(os.Stdout, fmt.Sprintf("%d UNEXPECTED ERRORS.", StyledTextContentSpecErrorCount))
}
